import{_ as e,o,c as r,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Rubrics","description":"","frontmatter":{"source":"assessment/rubrics.md"},"headers":[],"relativePath":"assessment/rubrics.md","filePath":"assessment/rubrics.md"}'),n={name:"assessment/rubrics.md"};function a(i,t,d,c,h,l){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="rubrics" tabindex="-1">Rubrics <a class="header-anchor" href="#rubrics" aria-label="Permalink to &quot;Rubrics&quot;">​</a></h1><blockquote><p>Scoring guides for every graded component. Each row is something a grader can see in your repo, on your live site or in your writing.</p></blockquote><p><strong>How to read these tables.</strong> Each rubric has criteria (rows) and four levels (columns). The number in bold is the points for that level.</p><table tabindex="0"><thead><tr><th>Level</th><th>Means</th></tr></thead><tbody><tr><td><strong>Exemplary</strong></td><td>Everything asked for, done carefully, with clear evidence. Beyond what most students do</td></tr><tr><td><strong>Proficient</strong></td><td>Everything asked for, done well. <strong>This is a good result</strong></td></tr><tr><td><strong>Developing</strong></td><td>Started, but important parts are missing or unclear</td></tr><tr><td><strong>Missing</strong></td><td>Not there</td></tr></tbody></table><p>Graders pick the level that best fits each row. If a row falls between two levels, they use the lower one and say what would lift it. Weights and how points turn into your course grade are in the <a href="./#how-grades-are-calculated">assessment README</a>.</p><p><strong>Rubric levels describe the work, not misconduct.</strong> If a piece of work seems to break the AI-use rules (for example, an AI-written <code>SPEC.md</code> or reflection) or seems fabricated, it is handled under <a href="./#academic-integrity">Academic integrity</a>, and no score is changed until the University process is complete.</p><p><strong>The six skills you must show without AI</strong> (<a href="./../resources/without-ai-skills.html">the list</a>) are practiced in the weekly exit tickets and the AI-off lab tasks. They count in the project rubrics below: the Tests rows, Project 2&#39;s key row, and the capstone&#39;s security and &quot;Code you can explain&quot; rows.</p><hr><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h2><p><strong>20% of the course, 185 points.</strong> The weekly homework below (110 points), your AI-off writing (70 points: weekly reflections, two peer reviews and the final reflection, <a href="#reflections-and-peer-reviews">below</a>) and the <a href="#capstone-pitch">capstone pitch</a> (5 points). Assignments are graded on completion and effort. Homework is graded on <strong>effort and completion of the core tier</strong>, not on polish. The core items for each week are the deliverables checklist in that week&#39;s <code>homework.md</code> (each week&#39;s folder is linked from the <a href="./../SYLLABUS.html#course-outline">course outline</a>). For week 12, the core items are the capstone&#39;s <a href="./../projects/capstone.html#milestones">Milestone 1</a> row, copied word for word. <a href="./../projects/capstone.html#milestones">Milestone 2</a> is spread over weeks 13 and 14: week 13&#39;s core items are its second feature type and section 3 of the security checklist, and week 14&#39;s are the rest of the Milestone 2 row.</p><p>Weekly homework for weeks 1–8 and 11–15 is scored out of 10, and the lowest <strong>two</strong> are dropped. <strong>Weeks 9 and 10 have no weekly homework score:</strong> their homework is <a href="#project-2">Project 2</a>. Week 16 (finals week) is graded in the <a href="#capstone">capstone</a>.</p><p>Some weekly deliverables are also parts of a project (for example, the week 1 page is the start of your home page). That&#39;s deliberate: the weekly score rewards doing the step on time, and the project rubric judges the finished result.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Core tasks</strong></td><td><strong>4</strong> · Every core item on the checklist is done</td><td><strong>3</strong> · All but one core item done</td><td><strong>2</strong> · All but two done; <strong>1</strong> · about half done</td><td><strong>0</strong> · Not submitted</td></tr><tr><td><strong>Save points and log</strong></td><td><strong>3</strong> · Several small commits with messages that say what changed; <code>PROMPTS.md</code> updated with what you changed or checked yourself; AI-assisted commits carry an <code>Assisted-by:</code> line (from week 3)</td><td><strong>2</strong> · Commits with clear messages; <code>PROMPTS.md</code> updated; from week 11, <code>Assisted-by:</code> lines on AI-assisted commits</td><td><strong>1</strong> · One large commit, or <code>PROMPTS.md</code> not updated</td><td><strong>0</strong> · No commits this week</td></tr><tr><td><strong>Checked it, or documented the blocker</strong></td><td><strong>3</strong> · Wrote the &quot;done when&quot; check before asking for the code (from week 6, an automated test wherever the logic allows it), tested the normal case and at least one edge case, and says what happened. If something didn&#39;t work: the exact error, what you tried, and what you&#39;ll try next</td><td><strong>2</strong> · Tested the normal case, or described the blocker with the error message</td><td><strong>1</strong> · &quot;It doesn&#39;t work&quot;, with no detail</td><td><strong>0</strong> · Nothing</td></tr></tbody></table><p>Homework that didn&#39;t work, with a clear record of the error and what you tried, can still earn full marks. That&#39;s the point of effort grading.</p><p><strong>Stretch tier:</strong> optional, and it never changes your score.</p><h3 id="capstone-pitch" tabindex="-1">Capstone pitch <a class="header-anchor" href="#capstone-pitch" aria-label="Permalink to &quot;Capstone pitch&quot;">​</a></h3><p><strong>5 points, part of Assignments.</strong> Due 72 hours before week 11 Studio A, on Canvas, from the <a href="./../projects/capstone.html#the-pitch">pitch template</a>.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Capstone pitch</strong> (🟡 AI limited)</td><td><strong>5</strong> · On time; every section of the pitch template specific, including a named user and a real plan B</td><td><strong>4</strong> · On time; every section filled in</td><td><strong>2</strong> · Late, or a section missing or vague</td><td><strong>0</strong> · No pitch</td></tr></tbody></table><hr><h2 id="labs" tabindex="-1">Labs <a class="header-anchor" href="#labs" aria-label="Permalink to &quot;Labs&quot;">​</a></h2><p><strong>20% of the course, 260 points.</strong> Labs are your in-class work in every studio, including the weekly exit ticket, and they are graded on completion and effort. There are <strong>30 studios</strong>, two a week in weeks 1–15: <strong>Studio A — Learn &amp; build</strong> and <strong>Studio B — Workshop</strong>. Each is scored out of 10, and your <strong>lowest four are dropped</strong>, so 260 points count. Timed builds such as <strong>Game in an Hour</strong> are graded on effort, not on whether you finish.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Lab work</strong></td><td><strong>4</strong> · Works through the core parts, reaches the checkpoints or asks for help early, and helps a neighbor at least once</td><td><strong>3</strong> · Works through the core parts and reaches most checkpoints</td><td><strong>1</strong> · Present but mostly off-task, or leaves early without arrangement</td><td><strong>0</strong> · Absent without arrangement</td></tr><tr><td><strong>Peer explanation and share-out</strong></td><td><strong>3</strong> · Explains their own work to a peer (in a swap, show and tell or debrief) <strong>and</strong> asks a genuine question about the peer&#39;s</td><td><strong>2</strong> · Takes part in the swap or share-out</td><td><strong>1</strong> · Minimal part (listens only)</td><td><strong>0</strong> · Doesn&#39;t take part</td></tr><tr><td><strong>Checkpoint or exit ticket</strong> (🔴 AI off for the ticket)</td><td><strong>3</strong> · The studio with that week&#39;s exit ticket (usually Studio B, weeks 1–14): every exit-ticket question answered in your own words. Correctness does <strong>not</strong> affect this score. Any other studio, including both in week 15: shares the end-of-studio checkpoint (a live URL, screenshot or commit), or the exact blocker</td><td><strong>2</strong> · All but one exit-ticket question answered; or shares where they got to, without the evidence</td><td><strong>1</strong> · Only one or two exit-ticket questions answered; or present at the checkpoint but shares nothing</td><td><strong>0</strong> · Absent; or no exit ticket</td></tr></tbody></table><p><strong>Missed a studio?</strong> The <a href="./#absences-and-make-up-work">make-up rules</a> follow U of I Regulations M-1 and M-3. For a recognized absence (official university activities, your own illness, family illness or care, other compelling circumstances, or religious observance), do the lab&#39;s core parts and, for the studio with that week&#39;s exit ticket, the exit ticket on Canvas within one week, for <strong>full credit</strong>. Other absences: within 48 hours, for up to 7 of the 10 points.</p><p><strong>No partner?</strong> With an odd number of students, or when your partner is away, explain your work to the instructor or a TA instead; that counts as the peer explanation. Online cohorts: &quot;present&quot; means camera or chat participation in the session, and swaps happen in breakout rooms.</p><hr><h2 id="project-1" tabindex="-1">Project 1 <a class="header-anchor" href="#project-1" aria-label="Permalink to &quot;Project 1&quot;">​</a></h2><p><strong>15% of the course, 40 points.</strong> For the <a href="./../projects/project-1-useful-tool.html">Project 1 brief</a>. Whether the tool works is one row out of six. Most points are for the spec, the tests and your process.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Spec</strong> (<code>SPEC.md</code>, 🟡 AI limited)</td><td><strong>10</strong> · Specific problem and user; at least 5 acceptance criteria in WHEN … THE APP SHALL … form, every one checkable by using the tool; at least 2 edge cases; out-of-scope list; wireframe; a <strong>Goldfish test</strong> logged in <code>PROMPTS.md</code> (what a fresh chat, given only <code>SPEC.md</code>, asked or got wrong) and the revision it led to; updated to match the final tool</td><td><strong>8</strong> · At least 5 criteria, nearly all checkable; at least 2 edge cases; out-of-scope list; wireframe; Goldfish test logged</td><td><strong>4</strong> · Fewer than 5 criteria, or several can&#39;t be checked (&quot;easy to use&quot;), or fewer than 2 edge cases</td><td><strong>0</strong> · No spec, or the unfilled template</td></tr><tr><td><strong>Tests</strong> (<code>TESTS.md</code>, <code>tests/</code>)</td><td><strong>8</strong> · A manual test for every criterion; at least 3 edge-case tests; every test has a dated result; <strong>at least 3 automated tests of the tool&#39;s pure logic</strong> passing with <code>node --test</code>, at least one of them an edge case and at least one written before the code it checks, output pasted in <code>TESTS.md</code>; at least one bug found by testing and fixed (logged with its commit)</td><td><strong>6</strong> · Tests for most criteria; at least 3 edge-case tests, with dated results; at least 3 automated tests of the pure logic passing</td><td><strong>3</strong> · Fewer than 3 edge-case tests, no results recorded, or fewer than 3 automated tests</td><td><strong>0</strong> · No <code>TESTS.md</code></td></tr><tr><td><strong>Works as specified</strong></td><td><strong>6</strong> · Live on GitHub Pages; every MUST criterion passes; data survives a reload; usable on a phone-width screen</td><td><strong>5</strong> · Live; most MUST criteria pass, and the README says which don&#39;t</td><td><strong>2</strong> · Live, but a core feature or the reload is broken and the README doesn&#39;t say so</td><td><strong>0</strong> · No live URL</td></tr><tr><td><strong>Plain code you own</strong></td><td><strong>6</strong> · Plain HTML, CSS and JavaScript; clear names; no dead code or placeholder comments (&quot;rest of code here&quot;); the pure logic is in <code>lib/</code>, separate from the page code; the function you wrote yourself in week 8 (&quot;You write it&quot;) is named in <code>PROMPTS.md</code> and you can point to it</td><td><strong>5</strong> · Plain files; minor leftovers; your own function named</td><td><strong>2</strong> · Large unused chunks, confusing names, or your own function not identified</td><td><strong>0</strong> · Framework or build output instead of plain files, or code missing from the repo</td></tr><tr><td><strong>Process</strong> (<code>PROMPTS.md</code> and commits)</td><td><strong>6</strong> · Key prompts in Goal · Context · Constraints · Done when form; what the AI got wrong and how you noticed; teach-back notes on AI-written changes; what you wrote or decided yourself; at least 6 commits with clear messages</td><td><strong>5</strong> · Several honest entries with what you changed; at least 6 commits</td><td><strong>2</strong> · Prompts only, with no notes on what happened; or one or two giant commits</td><td><strong>0</strong> · No <code>PROMPTS.md</code></td></tr><tr><td><strong>README</strong></td><td><strong>4</strong> · From the template: live URL, how to use, how it works, &quot;Authorization is enforced in: n/a…&quot;, an acceptance table that matches the tool, an honest known-issues list, credits</td><td><strong>3</strong> · Live URL, how to use, and an acceptance table</td><td><strong>1</strong> · A few lines; no acceptance table</td><td><strong>0</strong> · No README, or GitHub&#39;s default</td></tr></tbody></table><hr><h2 id="project-2" tabindex="-1">Project 2 <a class="header-anchor" href="#project-2" aria-label="Permalink to &quot;Project 2&quot;">​</a></h2><p><strong>15% of the course, 20 points.</strong> For the <a href="./../projects/ai-micro-app.html">Project 2 brief</a>, An AI Micro-App (weeks 9–10). It is the homework for weeks 9 and 10, which get no other weekly score. The capstone pitch, week 10&#39;s other deliverable, is scored in <a href="#capstone-pitch">Assignments</a>.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Key stays on the server</strong></td><td><strong>6</strong> · Key only in <code>.env</code> (ignored by git) and Vercel settings; only server code (<code>api/</code>, <code>lib/</code>) reads it; <code>npm run check:secrets</code> output shown (it checks your files and your git history); DevTools check on the production site described; the hidden-costs checklist done</td><td><strong>5</strong> · Key only on the server and not in git; checks done, evidence brief</td><td><strong>2</strong> · Key safe, but no checks done or no evidence</td><td><strong>0</strong> · A real key appears in the repo, its history, <code>public/</code> or the live site. Revoke it, fix it and resubmit within a week (and before the grade deadline) for up to Proficient</td></tr><tr><td><strong>Input limit and friendly errors</strong></td><td><strong>4</strong> · Own <code>MAX_INPUT_LENGTH</code> with a reason in <code>PROMPTS.md</code>; any new input also checked on the server; empty, too-long and missing-key cases each tried and showing a friendly message</td><td><strong>3</strong> · Own limit; the server check still works; empty and too-long cases tried</td><td><strong>1</strong> · Starter limits removed or bypassed, or raw errors shown to users</td><td><strong>0</strong> · No limits and no friendly errors</td></tr><tr><td><strong>Provider swap</strong></td><td><strong>3</strong> · Ran with two providers by changing only the three environment variables; <code>PROMPTS.md</code> names both, the models (from <code>npm run models</code>) and how the answers differed</td><td><strong>2</strong> · Ran with two providers; logged in <code>PROMPTS.md</code></td><td><strong>1</strong> · Tried a second provider; the blocker is documented</td><td><strong>0</strong> · Not attempted</td></tr><tr><td><strong>Made it your own, and deployed</strong></td><td><strong>3</strong> · A new job (system prompt), new page text and styling; production URL and a screenshot of it working submitted; tried in a private window</td><td><strong>2</strong> · New job; production URL and screenshot submitted</td><td><strong>1</strong> · Starter barely changed, or runs only in the Codespace</td><td><strong>0</strong> · Not submitted</td></tr><tr><td><strong>Documentation and tests</strong></td><td><strong>4</strong> · &quot;Where the key lives and who can read it&quot; (🔴 AI off, your own words) answers all seven questions accurately; <code>PROMPTS.md</code>; <code>npm test</code> passes, including at least two validation tests you wrote yourself, seen failing once on purpose</td><td><strong>3</strong> · Section present and mostly accurate; <code>npm test</code> passes with at least two validation tests of your own</td><td><strong>1</strong> · Section vague or missing; or no test of your own; or tests failing</td><td><strong>0</strong> · None of these</td></tr></tbody></table><p>The own friendly rate-limit (429) message is a stretch task this week, so it isn&#39;t scored here.</p><hr><h2 id="capstone" tabindex="-1">Capstone <a class="header-anchor" href="#capstone" aria-label="Permalink to &quot;Capstone&quot;">​</a></h2><p><strong>30% of the course, 100 points.</strong> For the <a href="./../projects/capstone.html">capstone brief</a>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>A working demo is required but not sufficient.</strong> Without a production URL where the main user story works, the capstone is capped at <strong>50/100</strong> until it runs. Agree a fix date with your instructor; it must fall before the University grade deadline (otherwise an Incomplete may be agreed under Regulation F). A working demo on its own earns only the &quot;Deployment&quot; row and part of the &quot;Feature types&quot; row. Most points are for the spec, tests, security, process, documentation and code you can explain.</p></div><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Spec</strong> (<code>SPEC.md</code>, 🟡 AI limited)</td><td><strong>15</strong> · Specific problem and user; at least 6 checkable WHEN … THE APP SHALL … criteria, including at least 2 edge cases and at least one per feature type; out-of-scope list; wireframe; a Goldfish test logged in <code>PROMPTS.md</code> and the revision it led to; updated to match the final app</td><td><strong>11</strong> · At least 5 checkable criteria, including 2 edge cases; out-of-scope list; wireframe; Goldfish test logged</td><td><strong>6</strong> · Fewer than 5 criteria, several not checkable, or no edge cases</td><td><strong>0</strong> · Missing, or the unfilled template</td></tr><tr><td><strong>Tests</strong> (<code>TESTS.md</code>, <code>tests/</code>)</td><td><strong>15</strong> · At least 3 automated tests passing (output shown), at least one of them an edge case; at least 3 manual edge-case tests with dated results; every MUST criterion has a test; tests written <strong>before</strong> the code they check, in a separate prompt (check first), with at least one recorded failing before it passed</td><td><strong>11</strong> · At least 3 automated tests passing; at least 3 manual edge-case tests with results</td><td><strong>6</strong> · Fewer than 3 of either, results not recorded, or tests failing</td><td><strong>0</strong> · No tests, or tests deleted or switched off to make them pass</td></tr><tr><td><strong>Security checklist with evidence</strong></td><td><strong>15</strong> · Every applicable item ticked, each with real evidence (command output, file name, screenshot link); if there&#39;s a database, RLS on every table with explicit grants and policies kept in <code>supabase/policies.sql</code>, and your own attack with the publishable key failed; the &quot;where authorization is enforced&quot; sentence is accurate; the found-and-fixed table is filled in</td><td><strong>11</strong> · Every applicable item ticked with evidence; minor gaps</td><td><strong>6</strong> · Items ticked without evidence, or a key item untested (such as the RLS attack)</td><td><strong>0</strong> · Missing. Also 0 if the grader finds a live secret, or a table that anyone can read or write <strong>beyond what <code>SPEC.md</code> and your README&#39;s &quot;Authorization is enforced in&quot; sentence say is intended</strong> (for example RLS off, or update or delete open to everyone). Fix it (revoke the key, add RLS and policies) and resubmit within a week, before the grade deadline, for up to Proficient</td></tr><tr><td><strong>Deployment and working demo</strong></td><td><strong>10</strong> · Production URL works in a private window on phone and laptop, with a screenshot submitted; environment variables set on the host, none in code; passes the polish checklist&#39;s accessibility items (labels, alt text, keyboard use, contrast)</td><td><strong>8</strong> · Production URL works and screenshot submitted; the main story works; one feature partly works and the README says so</td><td><strong>4</strong> · Live, but the main story is broken; or it runs only in the Codespace</td><td><strong>0</strong> · No production URL (see the cap above)</td></tr><tr><td><strong>Feature types</strong></td><td><strong>10</strong> · At least two feature types (pairs: three, or two plus the approved scope increase), each done the safe way (keys on the server; RLS on with policies; a chart drawn from the app&#39;s real data, with its data-prep function tested; external API errors and timeouts handled) and part of the main story</td><td><strong>8</strong> · At least two (pairs: three, or two plus the approved increase) working; one is bolted on or lacks error handling</td><td><strong>4</strong> · Only one feature type works</td><td><strong>0</strong> · None</td></tr><tr><td><strong>Process</strong> (<code>PROMPTS.md</code>, <code>AGENTS.md</code>, git)</td><td><strong>10</strong> · A <strong>teach-back</strong> (2–3 sentences: what changed and why) in <code>PROMPTS.md</code> before every agent commit; an <strong>ownership statement</strong> (&quot;What I wrote or decided myself&quot;) naming specific code, decisions and changes; plan-first prompts; what the agent got wrong and how you caught it; <code>AGENTS.md</code> tailored to this project, with a <strong>Scope</strong> section, and <strong>trial notes</strong> in <code>PROMPTS.md</code> (two tasks, whether the agent followed the file, one change you made); commits before and after agent tasks, with <code>Assisted-by:</code> lines; features merged through pull requests, each reviewed (by a partner, the instructor or a classmate, or a self-review against <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a> before merging)</td><td><strong>8</strong> · Teach-backs on most agent commits; an ownership statement; <code>AGENTS.md</code> with Scope and trial notes; regular commits with <code>Assisted-by:</code> lines; features merged through pull requests</td><td><strong>4</strong> · Few or no teach-backs, or a generic ownership statement; <code>AGENTS.md</code> unchanged or without Scope; a few giant commits. Pairs: no contribution statement on Canvas</td><td><strong>0</strong> · No <code>PROMPTS.md</code></td></tr><tr><td><strong>README and final presentation</strong></td><td><strong>10</strong> · A classmate could run the app from the README alone; production URL and screenshot; how-it-works table; where authorization is enforced; where each key lives; status table matches reality; an honest <strong>Known issues</strong> section (naming a real limitation never costs points); the tools you used and any fallback you switched to; credits. A five-minute presentation with a live demo of the problem, the main story and one edge case, saying where the keys and data live and naming one known issue</td><td><strong>8</strong> · README mostly complete, including Known issues; a presentation of about five minutes showing the main story working</td><td><strong>4</strong> · README missing how to run it or the status table; or the presentation runs well over time or doesn&#39;t show the app working</td><td><strong>0</strong> · Default README, or no presentation</td></tr><tr><td><strong>Code you can explain</strong></td><td><strong>15</strong> · Logic in <code>public/lib/</code> (or <code>lib/</code> for server-only code) with tests; clear names and small functions; no dead code, placeholders or disabled tests; every dependency intentional and named in the README; user text shown with <code>textContent</code>; in the questions after your final presentation (🔴 AI off) you explained the code you were asked about</td><td><strong>11</strong> · Readable and organized as in the starter; minor leftovers; the questions about your code went mostly well</td><td><strong>6</strong> · Large unexplained or unused chunks; unexplained dependencies; or, asked after your presentation, you couldn&#39;t explain a core part (an &quot;explain it or redo it&quot; follow-up can lift this row)</td><td><strong>0</strong> · Code you can&#39;t explain at all</td></tr></tbody></table><p><strong>Pairs:</strong> the same rubric, with the pair rules from the brief. In &quot;Feature types&quot;, Proficient and Exemplary need three feature types, or two plus the scope increase approved at the pitch. Without a signed contribution statement on Canvas, &quot;Process&quot; is at most Developing.</p><hr><h2 id="reflections-and-peer-reviews" tabindex="-1">Reflections and peer reviews <a class="header-anchor" href="#reflections-and-peer-reviews" aria-label="Permalink to &quot;Reflections and peer reviews&quot;">​</a></h2><p><strong>Part of Assignments: 70 of its 185 points.</strong> All of this is 🔴 AI off writing, submitted <strong>on Canvas</strong> (never in a repository). It&#39;s graded on specifics and honesty, not polish or grammar. Each piece is scored out of 5:</p><table tabindex="0"><thead><tr><th>Part</th><th>Points counted</th></tr></thead><tbody><tr><td>Weekly reflections (<a href="./../templates/REFLECTION.html">template</a>, 150–300 words) for weeks 1–9 and 11–14, lowest two dropped. Week 6&#39;s is the AI-free <strong>Verdict</strong> on your bake-off scorecard. Week 10 has none: Project 2&#39;s &quot;Where the key lives&quot; section takes its place and is graded in the <a href="#project-2">Project 2 rubric</a></td><td>55</td></tr><tr><td>Two written peer reviews: the <strong>week 5 spec review</strong> and the <strong>week 14 code review</strong></td><td>10</td></tr><tr><td>The final reflection (<a href="./../projects/capstone.html#final-reflection">prompts</a>), with your revised personal AI-use rules: the week 15 reflection</td><td>5</td></tr></tbody></table><p>Writing that appears to be AI-generated is handled under <a href="./#academic-integrity">Academic integrity</a>; no score is changed until the University process is complete.</p><table tabindex="0"><thead><tr><th>Piece</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Weekly reflection</strong></td><td><strong>5</strong> · Anchored in at least two concrete moments (a quoted prompt, an error message, a line of code, a decision; week 6: criterion IDs and what each builder did); explains one idea from the week correctly, with an example; names something still unclear and completes the confidence check</td><td><strong>4</strong> · One concrete moment described clearly; an idea explained, mostly correctly; something unclear named</td><td><strong>2</strong> · General statements only (&quot;AI is helpful&quot;), an idea named without explaining it, or &quot;nothing is unclear&quot;</td><td><strong>0</strong> · Not submitted</td></tr><tr><td><strong>Peer review</strong></td><td><strong>5</strong> · Every point located (a criterion ID, a file and line, a step on the live site); claims checked against the real spec or app, with disagreements phrased as questions; one real strength, the most important fix with a suggestion, and one question for the author</td><td><strong>4</strong> · Most points located and accurate; a strength and a fix</td><td><strong>2</strong> · Mostly general (&quot;looks good&quot;), only praise or only criticism, or a claim that&#39;s clearly wrong</td><td><strong>0</strong> · Not submitted, or unkind</td></tr><tr><td><strong>Final reflection</strong></td><td><strong>5</strong> · Several concrete moments across the course; compares what you felt you understood with what you could explain, in both directions; one Safe Loop habit that changed how you work; your revised AI-use rules with one changed rule explained; consistent with <code>PROMPTS.md</code></td><td><strong>4</strong> · Two or more concrete moments; compares felt and actual understanding with one example; the revised rules</td><td><strong>2</strong> · Mostly general, no comparison, no revised rules, or contradicts <code>PROMPTS.md</code></td><td><strong>0</strong> · Not submitted</td></tr></tbody></table><h3 id="peer-reviews" tabindex="-1">Peer reviews <a class="header-anchor" href="#peer-reviews" aria-label="Permalink to &quot;Peer reviews&quot;">​</a></h3><p>Both reviews are written on Canvas. Share yours with the author privately (a Canvas comment or email), never as an issue, pull-request comment or file in either repository, and refer to people by GitHub username.</p><ul><li><strong>Week 5 spec review:</strong> after the studio swap, write up your review of a classmate&#39;s <code>SPEC.md</code>: your prediction of what the app will do; every criterion that can&#39;t be tested (by ID) and why; one missing edge case; one strength; one question for the author.</li><li><strong>Week 14 code review:</strong> use the headings of the <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW template</a>. You may also leave ordinary comments on the author&#39;s pull request on GitHub; the graded review is the Canvas one.</li><li><strong>No classmate available?</strong> Your instructor assigns a review of a practice spec or repo instead.</li></ul><p>Invented problems cost points, as they do in UCSD&#39;s AI course, which penalizes reviews with made-up errors (<a href="https://ucsd-cse-115-215.github.io/sp26/index.html" target="_blank" rel="noreferrer">UCSD</a>).</p>',49)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
